-- PearlHub v0.1 relational schema
-- PostgreSQL 15+
-- Implementation baseline derived from the frozen PearlHub domain decisions.
-- Apply with a migration runner; do not run ad hoc against production.
--
-- Notes:
-- * UUIDs are generated by PostgreSQL.
-- * Artifact identity fields (name, slug, owner_id) are immutable.
-- * Artifact versions are append-only and immutable.
-- * Artifact deletion is represented by a tombstone; no hard-delete cascade is used.
-- * Binary/file bodies may live in object storage; storage_key is a locator, not content.
-- * Gemini API keys are deliberately not persisted.
-- * Users are deactivated (is_active=false), not hard-deleted, to preserve ownership and audit history.

BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TYPE artifact_visibility AS ENUM ('private', 'public', 'unlisted');
CREATE TYPE artifact_status AS ENUM ('active', 'tombstone');
CREATE TYPE lineage_relation AS ENUM ('fork');
CREATE TYPE import_provider AS ENUM ('github');
CREATE TYPE execution_record_kind AS ENUM ('playground', 'export');
CREATE TYPE compatibility_status AS ENUM ('compatible', 'incompatible', 'unknown', 'not_tested');
CREATE TYPE artifact_file_kind AS ENUM ('skill', 'knowledge', 'attachment', 'other');
CREATE TYPE usage_event_kind AS ENUM ('view', 'download', 'use', 'fork', 'clone', 'star', 'unstar');

-- Users / principals
CREATE TABLE users (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    handle              text NOT NULL,
    display_name        text,
    email               text,
    email_verified_at   timestamptz,
    avatar_url          text,
    is_active           boolean NOT NULL DEFAULT true,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT users_handle_nonblank CHECK (length(btrim(handle)) > 0)
);
CREATE UNIQUE INDEX users_handle_lower_uq ON users (lower(handle));
CREATE UNIQUE INDEX users_email_lower_uq ON users (lower(email)) WHERE email IS NOT NULL;

-- One row per canonical Pearl / Artifact identity.
CREATE TABLE artifacts (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    owner_id            uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    name                text NOT NULL,
    slug                text NOT NULL,
    summary             text,
    description         text,
    visibility          artifact_visibility NOT NULL DEFAULT 'private',
    status              artifact_status NOT NULL DEFAULT 'active',
    current_version_id  uuid,
    tombstone_snapshot  jsonb,
    deleted_at          timestamptz,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT artifacts_name_nonblank CHECK (length(btrim(name)) > 0),
    CONSTRAINT artifacts_slug_format CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    CONSTRAINT artifacts_status_tombstone_consistency CHECK (
        (status = 'active' AND deleted_at IS NULL AND tombstone_snapshot IS NULL)
        OR
        (status = 'tombstone' AND deleted_at IS NOT NULL
         AND tombstone_snapshot IS NOT NULL AND visibility = 'unlisted')
    ),
    CONSTRAINT artifacts_id_owner_uq UNIQUE (id, owner_id)
);
CREATE UNIQUE INDEX artifacts_slug_lower_uq ON artifacts (lower(slug));
CREATE INDEX artifacts_owner_created_idx ON artifacts (owner_id, created_at DESC);
CREATE INDEX artifacts_discovery_idx ON artifacts (visibility, updated_at DESC)
    WHERE status = 'active';
CREATE INDEX artifacts_tombstone_idx ON artifacts (deleted_at DESC)
    WHERE status = 'tombstone';

-- Immutable, complete published version snapshots.
CREATE TABLE artifact_versions (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    artifact_id         uuid NOT NULL REFERENCES artifacts(id) ON DELETE RESTRICT,
    version_number      integer NOT NULL,
    semver              text,
    title               text,
    changelog           text,
    canonical_snapshot  jsonb NOT NULL,
    content_hash        char(64) NOT NULL,
    published_at        timestamptz,
    created_by          uuid REFERENCES users(id) ON DELETE RESTRICT,
    created_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT artifact_versions_number_positive CHECK (version_number > 0),
    CONSTRAINT artifact_versions_hash_format CHECK (content_hash ~ '^[0-9a-f]{64}$'),
    CONSTRAINT artifact_versions_semver_format CHECK (
        semver IS NULL OR semver ~
        '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-((0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*)(\.(0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*))*))?(\+([0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*))?$'
    ),
    CONSTRAINT artifact_versions_artifact_number_uq UNIQUE (artifact_id, version_number),
    CONSTRAINT artifact_versions_artifact_id_uq UNIQUE (artifact_id, id)
);
ALTER TABLE artifacts
    ADD CONSTRAINT artifacts_current_version_fk
    FOREIGN KEY (id, current_version_id)
    REFERENCES artifact_versions (artifact_id, id)
    DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX artifact_versions_history_idx
    ON artifact_versions (artifact_id, version_number DESC);

-- Tags are normalized for discovery; tags attached to an artifact, not versioned content.
CREATE TABLE tags (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name        text NOT NULL,
    slug        text NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT tags_name_nonblank CHECK (length(btrim(name)) > 0),
    CONSTRAINT tags_slug_format CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$')
);
CREATE UNIQUE INDEX tags_slug_lower_uq ON tags (lower(slug));

CREATE TABLE artifact_tags (
    artifact_id uuid NOT NULL REFERENCES artifacts(id) ON DELETE RESTRICT,
    tag_id      uuid NOT NULL REFERENCES tags(id) ON DELETE RESTRICT,
    created_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (artifact_id, tag_id)
);
CREATE INDEX artifact_tags_tag_idx ON artifact_tags (tag_id, artifact_id);

-- Files in each immutable version. The body may be external object storage.
CREATE TABLE artifact_version_files (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    artifact_id         uuid NOT NULL,
    artifact_version_id uuid NOT NULL,
    path                text NOT NULL,
    kind                artifact_file_kind NOT NULL DEFAULT 'other',
    media_type          text,
    size_bytes          bigint NOT NULL DEFAULT 0,
    content_hash        char(64) NOT NULL,
    storage_key         text,
    text_content        text,
    metadata            jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT version_files_artifact_version_fk
        FOREIGN KEY (artifact_id, artifact_version_id)
        REFERENCES artifact_versions (artifact_id, id) ON DELETE RESTRICT,
    CONSTRAINT version_files_path_nonblank CHECK (length(btrim(path)) > 0),
    CONSTRAINT version_files_size_nonnegative CHECK (size_bytes >= 0),
    CONSTRAINT version_files_hash_format CHECK (content_hash ~ '^[0-9a-f]{64}$'),
    CONSTRAINT version_files_body_location CHECK (
        storage_key IS NOT NULL OR text_content IS NOT NULL
    ),
    CONSTRAINT version_files_version_path_uq UNIQUE (artifact_version_id, path)
);
CREATE INDEX version_files_version_idx
    ON artifact_version_files (artifact_version_id);

-- Skill descriptors in a version. Supports a Pearl containing multiple Skills.
CREATE TABLE artifact_version_skills (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    artifact_id         uuid NOT NULL,
    artifact_version_id uuid NOT NULL,
    skill_key           text NOT NULL,
    name                text NOT NULL,
    description         text,
    skill_markdown      text NOT NULL,
    embedded             boolean NOT NULL DEFAULT true,
    metadata             jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at           timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT version_skills_artifact_version_fk
        FOREIGN KEY (artifact_id, artifact_version_id)
        REFERENCES artifact_versions (artifact_id, id) ON DELETE RESTRICT,
    CONSTRAINT version_skills_key_nonblank CHECK (length(btrim(skill_key)) > 0),
    CONSTRAINT version_skills_name_nonblank CHECK (length(btrim(name)) > 0),
    CONSTRAINT version_skills_markdown_nonblank CHECK (length(btrim(skill_markdown)) > 0),
    CONSTRAINT version_skills_key_uq UNIQUE (artifact_version_id, skill_key)
);
CREATE INDEX version_skills_version_idx ON artifact_version_skills (artifact_version_id);

-- Fork is lineage. Clone is recorded separately and does not create a lineage edge.
CREATE TABLE artifact_lineage (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    parent_artifact_id  uuid NOT NULL REFERENCES artifacts(id) ON DELETE RESTRICT,
    child_artifact_id   uuid NOT NULL REFERENCES artifacts(id) ON DELETE RESTRICT,
    relation            lineage_relation NOT NULL DEFAULT 'fork',
    source_version_id   uuid,
    created_by          uuid REFERENCES users(id) ON DELETE RESTRICT,
    created_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT lineage_not_self CHECK (parent_artifact_id <> child_artifact_id),
    CONSTRAINT lineage_child_single_parent_uq UNIQUE (child_artifact_id),
    CONSTRAINT lineage_source_version_fk
        FOREIGN KEY (parent_artifact_id, source_version_id)
        REFERENCES artifact_versions (artifact_id, id) ON DELETE RESTRICT,
    CONSTRAINT lineage_parent_child_relation_uq
        UNIQUE (parent_artifact_id, child_artifact_id, relation)
);
CREATE INDEX artifact_lineage_parent_idx
    ON artifact_lineage (parent_artifact_id, created_at DESC);

CREATE TABLE artifact_clone_events (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    source_artifact_id  uuid NOT NULL REFERENCES artifacts(id) ON DELETE RESTRICT,
    cloned_artifact_id  uuid NOT NULL REFERENCES artifacts(id) ON DELETE RESTRICT,
    source_version_id   uuid,
    created_by          uuid REFERENCES users(id) ON DELETE RESTRICT,
    created_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT clone_not_self CHECK (source_artifact_id <> cloned_artifact_id),
    CONSTRAINT clone_source_version_fk
        FOREIGN KEY (source_artifact_id, source_version_id)
        REFERENCES artifact_versions (artifact_id, id) ON DELETE RESTRICT,
    CONSTRAINT clone_target_once_uq UNIQUE (cloned_artifact_id)
);
CREATE INDEX artifact_clone_source_idx
    ON artifact_clone_events (source_artifact_id, created_at DESC);

-- Fork lineage and clone provenance are permanent audit records.
CREATE FUNCTION reject_audit_record_mutation()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION '% records are append-only', TG_TABLE_NAME;
END;
$$;
CREATE TRIGGER artifact_lineage_append_only_trg
BEFORE UPDATE OR DELETE ON artifact_lineage
FOR EACH ROW EXECUTE FUNCTION reject_audit_record_mutation();
CREATE TRIGGER artifact_clone_events_append_only_trg
BEFORE UPDATE OR DELETE ON artifact_clone_events
FOR EACH ROW EXECUTE FUNCTION reject_audit_record_mutation();

-- GitHub import is provenance/source metadata, never a fork relation.
CREATE TABLE artifact_import_sources (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    artifact_id         uuid NOT NULL REFERENCES artifacts(id) ON DELETE RESTRICT,
    provider            import_provider NOT NULL DEFAULT 'github',
    source_url          text NOT NULL,
    repository_owner    text,
    repository_name     text,
    source_ref          text,
    source_path         text,
    commit_sha          text,
    imported_by         uuid REFERENCES users(id) ON DELETE RESTRICT,
    imported_at         timestamptz NOT NULL DEFAULT now(),
    metadata            jsonb NOT NULL DEFAULT '{}'::jsonb,
    CONSTRAINT import_source_url_nonblank CHECK (length(btrim(source_url)) > 0)
);
CREATE INDEX import_sources_artifact_idx
    ON artifact_import_sources (artifact_id, imported_at DESC);

-- Declared dependencies are immutable members of a specific artifact version.
CREATE TABLE artifact_version_dependencies (
    id                      uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    artifact_id             uuid NOT NULL,
    artifact_version_id     uuid NOT NULL,
    dependency_artifact_id  uuid NOT NULL REFERENCES artifacts(id) ON DELETE RESTRICT,
    declared_range           text NOT NULL,
    dependency_alias         text,
    is_optional              boolean NOT NULL DEFAULT false,
    metadata                 jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at               timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT dependencies_owner_version_fk
        FOREIGN KEY (artifact_id, artifact_version_id)
        REFERENCES artifact_versions (artifact_id, id) ON DELETE RESTRICT,
    CONSTRAINT dependencies_range_nonblank CHECK (length(btrim(declared_range)) > 0),
    CONSTRAINT dependencies_not_self CHECK (artifact_id <> dependency_artifact_id),
    CONSTRAINT dependencies_artifact_alias_nonblank CHECK (dependency_alias IS NULL OR length(btrim(dependency_alias)) > 0)
);
CREATE UNIQUE INDEX dependencies_artifact_alias_uq
    ON artifact_version_dependencies (artifact_version_id, dependency_artifact_id, coalesce(dependency_alias, ''));
CREATE INDEX version_dependencies_version_idx
    ON artifact_version_dependencies (artifact_version_id);
CREATE INDEX version_dependencies_target_idx
    ON artifact_version_dependencies (dependency_artifact_id);

-- Compatibility reports are tied to an exact Artifact Version.
CREATE TABLE compatibility_reports (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    artifact_id         uuid NOT NULL,
    artifact_version_id uuid NOT NULL,
    model_provider      text NOT NULL,
    model_id            text NOT NULL,
    status              compatibility_status NOT NULL DEFAULT 'unknown',
    report              jsonb NOT NULL DEFAULT '{}'::jsonb,
    tested_by           uuid REFERENCES users(id) ON DELETE RESTRICT,
    tested_at           timestamptz,
    created_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT compatibility_version_fk
        FOREIGN KEY (artifact_id, artifact_version_id)
        REFERENCES artifact_versions (artifact_id, id) ON DELETE RESTRICT,
    CONSTRAINT compatibility_provider_nonblank CHECK (length(btrim(model_provider)) > 0),
    CONSTRAINT compatibility_model_nonblank CHECK (length(btrim(model_id)) > 0)
);
CREATE INDEX compatibility_version_idx
    ON compatibility_reports (artifact_version_id, created_at DESC);
CREATE INDEX compatibility_model_idx
    ON compatibility_reports (model_provider, model_id, status);

-- A user may star an artifact once. Stars are not conflated with use events.
CREATE TABLE artifact_stars (
    artifact_id uuid NOT NULL REFERENCES artifacts(id) ON DELETE RESTRICT,
    user_id     uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    created_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (artifact_id, user_id)
);
CREATE INDEX artifact_stars_user_idx ON artifact_stars (user_id, created_at DESC);

-- Aggregate counters can be maintained asynchronously from usage_events.
CREATE TABLE artifact_metrics (
    artifact_id     uuid PRIMARY KEY REFERENCES artifacts(id) ON DELETE RESTRICT,
    views_count     bigint NOT NULL DEFAULT 0,
    downloads_count bigint NOT NULL DEFAULT 0,
    uses_count      bigint NOT NULL DEFAULT 0,
    forks_count     bigint NOT NULL DEFAULT 0,
    clones_count    bigint NOT NULL DEFAULT 0,
    stars_count     bigint NOT NULL DEFAULT 0,
    updated_at      timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT artifact_metrics_nonnegative CHECK (
        views_count >= 0 AND downloads_count >= 0 AND uses_count >= 0
        AND forks_count >= 0 AND clones_count >= 0 AND stars_count >= 0
    )
);

CREATE TABLE usage_events (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    artifact_id         uuid NOT NULL REFERENCES artifacts(id) ON DELETE RESTRICT,
    artifact_version_id uuid,
    actor_user_id       uuid REFERENCES users(id) ON DELETE RESTRICT,
    event_kind          usage_event_kind NOT NULL,
    request_id          text,
    metadata            jsonb NOT NULL DEFAULT '{}'::jsonb,
    occurred_at         timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT usage_event_version_fk
        FOREIGN KEY (artifact_id, artifact_version_id)
        REFERENCES artifact_versions (artifact_id, id) ON DELETE RESTRICT
);
CREATE INDEX usage_events_artifact_time_idx
    ON usage_events (artifact_id, occurred_at DESC);
CREATE INDEX usage_events_kind_time_idx
    ON usage_events (event_kind, occurred_at DESC);
CREATE INDEX usage_events_actor_time_idx
    ON usage_events (actor_user_id, occurred_at DESC)
    WHERE actor_user_id IS NOT NULL;

-- Playground / Export records keep declared ranges and the exact resolved versions.
-- No API key/token field is present by design.
CREATE TABLE execution_records (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    record_kind         execution_record_kind NOT NULL,
    artifact_id         uuid NOT NULL,
    artifact_version_id uuid NOT NULL,
    actor_user_id       uuid REFERENCES users(id) ON DELETE RESTRICT,
    model_provider      text,
    model_id            text,
    input_fingerprint   char(64),
    result_status       text,
    result_summary      jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT execution_artifact_version_fk
        FOREIGN KEY (artifact_id, artifact_version_id)
        REFERENCES artifact_versions (artifact_id, id) ON DELETE RESTRICT,
    CONSTRAINT execution_input_fingerprint_format CHECK (
        input_fingerprint IS NULL OR input_fingerprint ~ '^[0-9a-f]{64}$'
    )
);
CREATE INDEX execution_records_artifact_time_idx
    ON execution_records (artifact_id, created_at DESC);
CREATE INDEX execution_records_actor_time_idx
    ON execution_records (actor_user_id, created_at DESC)
    WHERE actor_user_id IS NOT NULL;

CREATE TABLE execution_dependency_resolutions (
    id                          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    execution_record_id         uuid NOT NULL REFERENCES execution_records(id) ON DELETE RESTRICT,
    dependency_id               uuid NOT NULL REFERENCES artifact_version_dependencies(id) ON DELETE RESTRICT,
    declared_range              text NOT NULL,
    resolved_artifact_id        uuid NOT NULL,
    resolved_artifact_version_id uuid NOT NULL,
    resolved_semver             text,
    resolved_content_hash       char(64) NOT NULL,
    created_at                  timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT resolution_version_fk
        FOREIGN KEY (resolved_artifact_id, resolved_artifact_version_id)
        REFERENCES artifact_versions (artifact_id, id) ON DELETE RESTRICT,
    CONSTRAINT resolution_range_nonblank CHECK (length(btrim(declared_range)) > 0),
    CONSTRAINT resolution_hash_format CHECK (resolved_content_hash ~ '^[0-9a-f]{64}$'),
    CONSTRAINT execution_dependency_once_uq UNIQUE (execution_record_id, dependency_id)
);
CREATE INDEX dependency_resolutions_resolved_version_idx
    ON execution_dependency_resolutions (resolved_artifact_id, resolved_artifact_version_id);

CREATE FUNCTION validate_dependency_resolution()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    v_execution_artifact_version uuid;
    v_declared_artifact_id uuid;
    v_declared_range text;
BEGIN
    SELECT artifact_version_id INTO v_execution_artifact_version
      FROM execution_records WHERE id = NEW.execution_record_id;
    SELECT dependency_artifact_id, declared_range
      INTO v_declared_artifact_id, v_declared_range
      FROM artifact_version_dependencies WHERE id = NEW.dependency_id;

    IF v_execution_artifact_version IS NULL OR v_declared_artifact_id IS NULL THEN
        RAISE EXCEPTION 'Execution record and declared dependency must exist';
    END IF;
    IF NEW.declared_range IS DISTINCT FROM v_declared_range THEN
        RAISE EXCEPTION 'Resolved dependency declared_range must match the immutable declaration';
    END IF;
    IF NEW.resolved_artifact_id IS DISTINCT FROM v_declared_artifact_id THEN
        RAISE EXCEPTION 'Resolved artifact must match the declared dependency target';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM artifact_version_dependencies d
         WHERE d.id = NEW.dependency_id
           AND d.artifact_version_id = v_execution_artifact_version
    ) THEN
        RAISE EXCEPTION 'Dependency declaration must belong to the execution record version';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER dependency_resolution_consistency_trg
BEFORE INSERT OR UPDATE ON execution_dependency_resolutions
FOR EACH ROW EXECUTE FUNCTION validate_dependency_resolution();

-- Identity fields and published versions are protected at the database boundary.
CREATE FUNCTION enforce_artifact_identity_immutable()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.name IS DISTINCT FROM OLD.name
       OR NEW.slug IS DISTINCT FROM OLD.slug
       OR NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN
        RAISE EXCEPTION 'Artifact name, slug, and owner are immutable';
    END IF;

    IF OLD.status = 'tombstone' AND (
        NEW.status IS DISTINCT FROM OLD.status
        OR NEW.tombstone_snapshot IS DISTINCT FROM OLD.tombstone_snapshot
        OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
        OR NEW.visibility IS DISTINCT FROM OLD.visibility
        OR NEW.summary IS DISTINCT FROM OLD.summary
        OR NEW.description IS DISTINCT FROM OLD.description
        OR NEW.current_version_id IS DISTINCT FROM OLD.current_version_id
    ) THEN
        RAISE EXCEPTION 'Artifact tombstones and their snapshots are immutable';
    END IF;

    IF OLD.status = 'active' AND NEW.status = 'tombstone'
       AND (NEW.visibility <> 'unlisted' OR NEW.deleted_at IS NULL OR NEW.tombstone_snapshot IS NULL) THEN
        RAISE EXCEPTION 'Deletion must create an unlisted tombstone with an immutable snapshot';
    END IF;

    RETURN NEW;
END;
$$;
CREATE TRIGGER artifacts_identity_immutable_trg
BEFORE UPDATE ON artifacts
FOR EACH ROW EXECUTE FUNCTION enforce_artifact_identity_immutable();

CREATE FUNCTION tombstone_artifact_before_delete()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    v_snapshot jsonb;
BEGIN
    IF OLD.status = 'tombstone' THEN
        RETURN NULL;
    END IF;

    SELECT jsonb_build_object(
        'schema_version', 1,
        'captured_at', clock_timestamp(),
        'artifact', jsonb_build_object(
            'id', OLD.id, 'owner_id', OLD.owner_id, 'name', OLD.name, 'slug', OLD.slug,
            'summary', OLD.summary, 'description', OLD.description,
            'visibility', OLD.visibility, 'status', OLD.status,
            'current_version_id', OLD.current_version_id, 'created_at', OLD.created_at
        ),
        'versions', COALESCE((
            SELECT jsonb_agg(
                to_jsonb(v) || jsonb_build_object(
                    'files', COALESCE((SELECT jsonb_agg(to_jsonb(f)) FROM artifact_version_files f WHERE f.artifact_version_id = v.id), '[]'::jsonb),
                    'skills', COALESCE((SELECT jsonb_agg(to_jsonb(sk)) FROM artifact_version_skills sk WHERE sk.artifact_version_id = v.id), '[]'::jsonb),
                    'dependencies', COALESCE((SELECT jsonb_agg(to_jsonb(d)) FROM artifact_version_dependencies d WHERE d.artifact_version_id = v.id), '[]'::jsonb)
                ) ORDER BY v.version_number
            ) FROM artifact_versions v WHERE v.artifact_id = OLD.id
        ), '[]'::jsonb),
        'lineage', jsonb_build_object(
            'parents', COALESCE((SELECT jsonb_agg(to_jsonb(l)) FROM artifact_lineage l WHERE l.child_artifact_id = OLD.id), '[]'::jsonb),
            'children', COALESCE((SELECT jsonb_agg(to_jsonb(l)) FROM artifact_lineage l WHERE l.parent_artifact_id = OLD.id), '[]'::jsonb),
            'clones_from', COALESCE((SELECT jsonb_agg(to_jsonb(c)) FROM artifact_clone_events c WHERE c.cloned_artifact_id = OLD.id), '[]'::jsonb),
            'clones_to', COALESCE((SELECT jsonb_agg(to_jsonb(c)) FROM artifact_clone_events c WHERE c.source_artifact_id = OLD.id), '[]'::jsonb)
        ),
        'import_sources', COALESCE((SELECT jsonb_agg(to_jsonb(i)) FROM artifact_import_sources i WHERE i.artifact_id = OLD.id), '[]'::jsonb),
        'tags', COALESCE((SELECT jsonb_agg(to_jsonb(t)) FROM artifact_tags atg JOIN tags t ON t.id = atg.tag_id WHERE atg.artifact_id = OLD.id), '[]'::jsonb)
    ) INTO v_snapshot;

    UPDATE artifacts
       SET status = 'tombstone', visibility = 'unlisted',
           deleted_at = clock_timestamp(), tombstone_snapshot = v_snapshot
     WHERE id = OLD.id;
    RETURN NULL; -- cancel physical DELETE; the row is now a tombstone
END;
$$;
CREATE TRIGGER artifacts_delete_to_tombstone_trg
BEFORE DELETE ON artifacts
FOR EACH ROW EXECUTE FUNCTION tombstone_artifact_before_delete();

CREATE FUNCTION reject_user_hard_delete()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'Users must be deactivated and processed through the account-deletion workflow; hard DELETE is prohibited';
END;
$$;
CREATE TRIGGER users_no_hard_delete_trg
BEFORE DELETE ON users
FOR EACH ROW EXECUTE FUNCTION reject_user_hard_delete();

CREATE FUNCTION enforce_artifact_version_lifecycle()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Artifact versions are append-only and cannot be deleted';
    END IF;

    -- The only permitted parent-row update is publishing an initially-unpublished
    -- version. All content-bearing columns remain unchanged.
    IF OLD.published_at IS NULL AND NEW.published_at IS NOT NULL
       AND NEW.id IS NOT DISTINCT FROM OLD.id
       AND NEW.artifact_id IS NOT DISTINCT FROM OLD.artifact_id
       AND NEW.version_number IS NOT DISTINCT FROM OLD.version_number
       AND NEW.semver IS NOT DISTINCT FROM OLD.semver
       AND NEW.title IS NOT DISTINCT FROM OLD.title
       AND NEW.changelog IS NOT DISTINCT FROM OLD.changelog
       AND NEW.canonical_snapshot IS NOT DISTINCT FROM OLD.canonical_snapshot
       AND NEW.content_hash IS NOT DISTINCT FROM OLD.content_hash
       AND NEW.created_by IS NOT DISTINCT FROM OLD.created_by
       AND NEW.created_at IS NOT DISTINCT FROM OLD.created_at THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'Published Artifact Versions are immutable';
END;
$$;
CREATE TRIGGER artifact_versions_lifecycle_trg
BEFORE UPDATE OR DELETE ON artifact_versions
FOR EACH ROW EXECUTE FUNCTION enforce_artifact_version_lifecycle();

CREATE FUNCTION guard_version_snapshot_child_write()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    v_version_id uuid;
    v_published_at timestamptz;
BEGIN
    IF TG_OP = 'UPDATE' AND (
        NEW.artifact_id IS DISTINCT FROM OLD.artifact_id
        OR NEW.artifact_version_id IS DISTINCT FROM OLD.artifact_version_id
    ) THEN
        RAISE EXCEPTION 'Snapshot rows cannot be moved between artifacts or versions';
    END IF;

    IF TG_OP = 'DELETE' THEN
        v_version_id := OLD.artifact_version_id;
    ELSE
        v_version_id := NEW.artifact_version_id;
    END IF;

    SELECT published_at INTO v_published_at
      FROM artifact_versions WHERE id = v_version_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Artifact Version % does not exist', v_version_id;
    END IF;
    IF v_published_at IS NOT NULL THEN
        RAISE EXCEPTION 'Published Artifact Version snapshot rows are immutable';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;

CREATE TRIGGER version_files_lifecycle_trg
BEFORE INSERT OR UPDATE OR DELETE ON artifact_version_files
FOR EACH ROW EXECUTE FUNCTION guard_version_snapshot_child_write();
CREATE TRIGGER version_skills_lifecycle_trg
BEFORE INSERT OR UPDATE OR DELETE ON artifact_version_skills
FOR EACH ROW EXECUTE FUNCTION guard_version_snapshot_child_write();
CREATE TRIGGER version_dependencies_lifecycle_trg
BEFORE INSERT OR UPDATE OR DELETE ON artifact_version_dependencies
FOR EACH ROW EXECUTE FUNCTION guard_version_snapshot_child_write();

CREATE FUNCTION require_version_published_at_commit()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM artifact_versions WHERE id = NEW.id AND published_at IS NULL) THEN
        RAISE EXCEPTION 'Artifact Version % must be published before transaction commit', NEW.id;
    END IF;
    RETURN NULL;
END;
$$;
CREATE CONSTRAINT TRIGGER artifact_versions_must_publish_trg
AFTER INSERT ON artifact_versions
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION require_version_published_at_commit();

CREATE FUNCTION validate_current_version_published()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.current_version_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM artifact_versions v
         WHERE v.id = NEW.current_version_id
           AND v.artifact_id = NEW.id
           AND v.published_at IS NOT NULL
    ) THEN
        RAISE EXCEPTION 'current_version_id must reference a published version of the same artifact';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER artifacts_current_version_published_trg
BEFORE INSERT OR UPDATE OF current_version_id ON artifacts
FOR EACH ROW EXECUTE FUNCTION validate_current_version_published();

-- updated_at maintenance for mutable aggregate / user / artifact rows.
CREATE FUNCTION set_updated_at()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;
CREATE TRIGGER users_set_updated_at_trg
BEFORE UPDATE ON users
FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER artifacts_set_updated_at_trg
BEFORE UPDATE ON artifacts
FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER artifact_metrics_set_updated_at_trg
BEFORE UPDATE ON artifact_metrics
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

COMMIT;
